CREATE TABLE product_category(id BIGINT NOT NULL,parent_id BIGINT NULL,code VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,name VARCHAR(100) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,sort_order INT NOT NULL DEFAULT 0,version BIGINT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY(id),UNIQUE KEY uk_product_category_code(code),INDEX idx_product_category_parent(parent_id,sort_order));
CREATE TABLE product_brand(id BIGINT NOT NULL,code VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,name VARCHAR(100) NOT NULL,logo_url VARCHAR(512) NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,version BIGINT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY(id),UNIQUE KEY uk_product_brand_code(code));
CREATE TABLE product_spu(id BIGINT NOT NULL,category_id BIGINT NOT NULL,brand_id BIGINT NULL,name VARCHAR(200) NOT NULL,description TEXT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'DRAFT',version BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),PRIMARY KEY(id),INDEX idx_product_spu_category_status(category_id,status),CONSTRAINT fk_product_spu_category FOREIGN KEY(category_id) REFERENCES product_category(id),CONSTRAINT fk_product_spu_brand FOREIGN KEY(brand_id) REFERENCES product_brand(id));
CREATE TABLE product_sku(id BIGINT NOT NULL,spu_id BIGINT NOT NULL,sku_code VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,price DECIMAL(18,2) NOT NULL,currency CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,traceability_code VARCHAR(128) NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'DRAFT',version BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),PRIMARY KEY(id),UNIQUE KEY uk_product_sku_code(sku_code),INDEX idx_product_sku_spu_status(spu_id,status),CONSTRAINT fk_product_sku_spu FOREIGN KEY(spu_id) REFERENCES product_spu(id),CONSTRAINT chk_product_sku_price CHECK(price>=0));
CREATE TABLE product_image(id BIGINT NOT NULL,spu_id BIGINT NOT NULL,sku_id BIGINT NULL,url VARCHAR(512) NOT NULL,sort_order INT NOT NULL DEFAULT 0,PRIMARY KEY(id),INDEX idx_product_image_spu_sort(spu_id,sort_order),CONSTRAINT fk_product_image_spu FOREIGN KEY(spu_id) REFERENCES product_spu(id) ON DELETE CASCADE,CONSTRAINT fk_product_image_sku FOREIGN KEY(sku_id) REFERENCES product_sku(id) ON DELETE CASCADE);
CREATE TABLE product_trace_event(id BIGINT NOT NULL,sku_id BIGINT NOT NULL,event_type VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,location_name VARCHAR(200) NULL,occurred_at DATETIME(6) NOT NULL,details_json JSON NULL,PRIMARY KEY(id),INDEX idx_product_trace_sku_time(sku_id,occurred_at),CONSTRAINT fk_product_trace_sku FOREIGN KEY(sku_id) REFERENCES product_sku(id));
